"""検査・非公開共有済みの第8話を、原寸メディアを含めずGitHub用にまとめる。"""
from pathlib import Path
from PIL import Image
import shutil,json
from wom08_produce import ROOT,REPO,read,save
DATE='20261030'
def main():
 share=read(ROOT/'records/sharing.json');assert share['status']=='verified' and share['draft'] and len(share['assets'])==8
 for k in ['qc_v01','continuous_qc','final_video_motion','episode_specific_qc','subtitle_layout_validation']:assert read(ROOT/f'records/{k}.json')['passed'],k
 out=REPO/f'new-channel/wom08_確認版_v01_{DATE}';(out/'records').mkdir(parents=True,exist_ok=True);(out/'確認画像').mkdir(exist_ok=True)
 for p in (ROOT/'records').glob('*.json'):shutil.copy2(p,out/'records'/p.name)
 for pattern in ['*.srt','*.md','*.csv','*pronunciation*.txt']:
  for p in (ROOT/'deliverables').glob(pattern):(out/p.name).write_text(p.read_text().rstrip()+'\n') if p.suffix in ['.md','.csv'] else shutil.copy2(p,out/p.name)
 for pattern in ['compositions_*.jpg','continuous_*_sheet_*.jpg','opening_*.jpg','subtitle_*.jpg','V01_source_contact.jpg']:
  for p in (ROOT/'review').glob(pattern):
   im=Image.open(p).convert('RGB');im.thumbnail((1280,1280));dst=out/'確認画像'/p.name;im.save(dst,quality=85,optimize=True);assert dst.stat().st_size<1000000
 q=read(ROOT/'records/qc_v01.json');a=read(ROOT/'records/audio_qc.json');motion=read(ROOT/'records/final_video_motion.json');ep=read(ROOT/'records/episode_specific_qc.json');sub=read(ROOT/'records/subtitle_validation.json');kl=read(ROOT/'records/kling_generation.json');m=read(ROOT/'records/master_timeline.json')
 ratios=[x['ratio'] for x in motion['checks'] if x['motion_ratio_applicable']];counts={x['key']:1 for x in ep['source_usage']}
 previous=read(REPO/'new-channel/wom07_確認版_v01_20261029/audio_qc.json')
 comparison={'method':'Both records use 32768-sample Hann-window FFT at 24 kHz; compare the recorded final ducked BGM streams, with different track selections and narrative timing.','EP007':{l:previous['languages'][l]['band_percent'] for l in ['en','ja']},'EP008':{l:a['languages'][l]['band_percent'] for l in ['en','ja']}}
 save(ROOT/'records/bgm_band_comparison.json',comparison);save(out/'records/bgm_band_comparison.json',comparison)
 lines=['# Quiet Origins 第8話「ツタンカーメンの呪い」確認版v01（2026-10-30）','','**確認版を制作し、技術検査と非公開Draft共有を完了。Claudeの内容確認・本人の全編試聴待ち。**','','承認済み台本v02.1（`55e7812`）の日英JSONを使用。追加修正案6区間を採用した最新版の本文を維持した。音声入力の発音補正は字幕を変更せず、初回の無置換音声も保全した。','','## 見る・取得する','',f"[非公開Draft Release]({share['release_url']})、Release ID **`{share['release_id']}`**。8資産をRelease ID指定のRESTで再取得し、全件サイズ・SHA-256一致、匿名アクセス404、Draftのままを確認。",'','- `EP008_Tutankhamun_ja_v01_subtitled_review_1080p30.mp4`：日本語・字幕付き確認版。','- `EP008_Tutankhamun_en_v01_subtitled_review_1080p30.mp4`：英語・字幕付き確認版。','- `EP008_Tutankhamun_{en,ja}_v01_1080p30.mp4`：字幕焼き込みなしの本編。','- `EP008_audio_and_subtitles.zip`：英日WAV/M4A/SRT、発音確認抜粋と時刻一覧。','- `EP008_thumbnails_and_metadata.zip`：サムネ3案・168px比較、英日投稿情報、出典。','- `EP008_QA_records.zip`：検査記録と連続デコード画像。','- `EP008_AI_scene_review.zip`：P14のKling原動画1本。','','Claudeはブラウザーの通常のダウンロードURLだけで取得できない場合、`gh api repos/yasukawa1980/youtube/releases/RELEASE_ID` でassetsのIDを調べ、`gh api -H "Accept: application/octet-stream" repos/yasukawa1980/youtube/releases/assets/ASSET_ID > FILE` で取得する。IDとハッシュは [sharing.json](records/sharing.json) に記録。','','## 実測結果','',f"- 共通尺 **{q['duration_seconds']:.6f}秒**、**{q['frames']:,}フレーム**。H.264 High / yuv420p / 1920×1080 / 30fps固定。英日本編の映像ストリーム同一。",'- 全25ショット（共通OP・エンドカードを含む）を個別デコーダーから非圧縮フレームとして単一エンコーダーへ入力。圧縮連結なし。','- 本編・字幕付き確認版の英日4本を先頭から末尾まで連続デコードし、警告・エラー0。英日各25ショットの先頭・中央・末尾を連続デコードから抽出。英日本編の各フレームの形式が1920×1080/yuv420p、SPS profile_idc=100のみであることを確認。',f"- 動く17ショットの全隣接フレームを測定。最終動画のp95÷中央値は最大 **{max(ratios):.6f}**（2.5以下）。文字カード・模式図・クレジットの6ショットは静止原画の全差分0を検証し、最終コーデック由来の差分を別途保存。",f"- 字幕：英{sub['en']['count']}件・日{sub['ja']['count']}件。最短1.4秒以上、2行以内、1行最大英{sub['en']['max_line_chars']}字・日{sub['ja']['max_line_chars']}字。台本との一致を確認。全ページを標準・拡大の2サイズで実際に描画し、画面本文と非重複。",f"- 日本語の区間末尾の待ちは最大 **{ep['max_ja_wait_seconds']:.3f}秒**。発話は引き伸ばさず文間へ配分。",f"- 共通OPは{m['brand_intervals']['opening'][0]:.6f}〜{m['brand_intervals']['opening'][1]:.6f}秒（P02後、4秒）。エンドカードは{m['brand_intervals']['endcard'][0]:.6f}〜{m['brand_intervals']['endcard'][1]:.6f}秒（末尾10秒）。元ファイルのハッシュ・ミックス内ブランド音声のサンプル一致。",'- 原典16素材とAI1素材はそれぞれ1ショット。扉の別カットはB286・B299・B300の3枚。P04は制作依頼どおりB170→B164（JSONのvisuals配列は参考扱い）。','- 新聞の前景・拡大部分・ぼかし背景はすべて記録した記事段だけから作成し、カメラもその合成画像内で動く。N01の左隣の顔写真、N02の列車事故大見出しは取得範囲に入らない。','- 0・1・2・3秒の画面を英日とも記録。0秒からB286を全面表示し、動きがあることを画素差でも確認。','- 刊本p258の実際の字は **Live thy Ka**。調査の略記May thy Kaではなく原画像を表示。承認済みの語りは祝福の意味の要約なので維持。','','## 音・生成の記録','']
 for l,label in [('en','英語'),('ja','日本語')]:
  x=a['languages'][l];b=x['band_percent'];lines.append(f"- {label}：{x['levels']['input_i']} LUFS、{x['levels']['input_tp']} dBTP。語り{x['voice_during_narration_dbfs']:.3f} / 語り中BGM{x['bgm_during_narration_dbfs']:.3f} / 切れ目BGM{x['bgm_during_full_boost_breaks_dbfs']:.3f} dBFS。帯域比 <200Hz {b['below_200Hz']:.3f}% / 200〜2kHz {b['200_to_2000Hz']:.3f}% / ≥2kHz {b['at_or_above_2000Hz']:.3f}%。")
 lines += ['- BGMはQO_THEME_A02のみ。100Hzハイパス、2〜4kHz付近を3.5dB下げ、クロスフェード3秒。P07は切れ目の+6dBを無効にした。第7話の記録との比較は [帯域比較](records/bgm_band_comparison.json)。',f"- Kling 3.0、ろうそく1本。消費 **{kl['actual_credits_spent']}/{kl['cap']}クレジット**、残高 **{kl['initial_balance']}→{kl['final_balance']}**。追加購入なし。1秒ごとの標本画像では人物・文字・墓・現代物は見られず、炎とろうそくの形は安定。標本による確認と明記し、全フレームの意味内容の自動認証とはしない。",'- 読み補正：英語Tutankhamun、Carnarvon、Louisa May Alcottは制作依頼の読み案に沿う音素入力。年号1869・1892・1939・2400 BC、Lot No.249の読み、日本語「競売番号249」を補正。無置換の初回音声と設定を保全し、変更箇所と時刻は [reading_replacements.json](records/reading_replacements.json) と発音抜粋に記録。人による聴感の最終確認は未実施。','','## 次の確認','', '1. Claude：台本・出典表示・資料の向き・新聞の切り出し・図解・サムネ3案。','2. 本人：英日発音確認抜粋と全編。P07〜08の調子、語りとBGMの聞きやすさ、先頭からの連続再生を確認。','3. サムネA/B/Cを選び、本編合格後に投稿依頼へ。公開目標11/4 09:00 JST。','','サムネ：A NOT IN THE TOMB ／ B WHO STARTED IT? ／ C THE CURSE?。[168px比較](../サムネ確認用/wom08/wom08_サムネ168px比較_20261029.jpg)。','',f'ローカル：[日本語・字幕付き確認版]({ROOT}/deliverables/EP008_Tutankhamun_ja_v01_subtitled_review_1080p30.mp4)。制作を10/29に開始したためMacの作業フォルダ名は `確認版_v01_20261029`、共有・完成記録は10/30。フォルダの移動はしていない。','', 'YouTube未投稿。Releaseは非公開Draft。動画・音源・原寸・中間物はGitに含めていない。','']
 text='\n'.join(lines);(out/'README.md').write_text(text);(REPO/f'new-channel/wom08_制作結果_v01_{DATE}.md').write_text(text.replace('(records/','(wom08_確認版_v01_20261030/records/').replace('(../サムネ確認用/','(サムネ確認用/'))
 (out/'SHA256SUMS_shared.txt').write_text(''.join(f"{x['sha256']}  {x['name']}\n" for x in share['assets']))
 (REPO/f'new-channel/wom08_制作進捗_{DATE}.md').write_text('# 第8話 制作進捗（2026-10-30）\n\n承認済みv02.1の確認版v01を制作し、技術検査と非公開Draft共有を完了。次はClaudeの内容確認と本人の試聴。\n\n[制作結果](wom08_制作結果_v01_20261030.md)／[取得案内](wom08_確認版_v01_20261030/README.md)。\n')
 print('FINALIZED',out)
if __name__=='__main__':main()
